import numpy as np


class PathRelinkMixedES:
    """
    Mixed-integer constrained ES refined from CreditScanMixedES.
    - Violation-directed best-value repair of near-feasible offspring (kept).
    - Best-improvement coordinate sweep on the incumbent, then adaptive 1+1 search (kept).
    - NEW: archive path-relinking. The incumbent is walked toward another feasible archive
      member, one differing gene at a time (integers jump to the target value, continuous
      genes move to the midpoint). Only improving steps are kept, so every polish step
      explores a new region between two good feasible points.
    - Deb feasibility rules, stochastic-ranking survival, evaluation cache, archive-seeded restarts.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        dim = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vtypes = [str(t) for t in func.variable_types]
        is_int = np.array([t != "continuous" for t in vtypes], dtype=bool)
        is_cat = np.array([t == "categorical" for t in vtypes], dtype=bool)
        is_cont = ~is_int

        nv = np.ones(dim, dtype=int)
        if is_int.any():
            nv[is_int] = np.asarray(func.n_values, dtype=int)[is_int]

        width = ub - lb
        int_idx = np.where(is_int)[0]
        cont_idx = np.where(is_cont)[0]
        n_int, n_cont = len(int_idx), len(cont_idx)
        min_pm = 1.0 / max(n_int, 1)

        gene_w = np.ones(dim)
        st = {"evals": 0, "best_f": np.inf, "best_x": None}
        cache = {}
        archive = []
        ARCH_CAP = 12

        # ---------------- helpers ----------------
        def sanitize(x):
            x = np.clip(np.asarray(x, dtype=float), lb, ub)
            if n_int:
                x[int_idx] = np.clip(np.round(x[int_idx]), 0, nv[int_idx] - 1)
            return x

        def can():
            return st["evals"] < budget

        def evaluate(x):
            x = sanitize(x)
            k = x.tobytes()
            if k in cache:
                return dict(cache[k])
            if not can():
                return None
            f, g = func(x)
            st["evals"] += 1
            f = float(f)
            g = np.asarray(g, dtype=float).ravel()
            v = float(np.sum(np.maximum(g, 0.0)))
            if not np.isfinite(v):
                v = 1e30
            if not np.isfinite(f):
                f = np.inf
                v = max(v, 1.0)
            feas = (v <= 0.0) and np.isfinite(f)
            ind = {"x": x, "f": f, "v": v, "feas": feas, "sigma": 0.2, "pm": 0.1}
            cache[k] = ind
            if feas:
                if f < st["best_f"]:
                    st["best_f"] = f
                    st["best_x"] = x.copy()
                add_archive(ind)
            return dict(ind)

        def add_archive(ind):
            for a in archive:
                if np.array_equal(a["x"], ind["x"]):
                    return
            archive.append({"x": ind["x"].copy(), "f": ind["f"], "v": 0.0, "feas": True,
                            "sigma": 0.2, "pm": 0.1})
            archive.sort(key=lambda a: a["f"])
            del archive[ARCH_CAP:]

        def key(ind):
            return (0, ind["f"]) if ind["feas"] else (1, ind["v"])

        def better(a, b):
            return key(a) < key(b)

        def pick_gene(int_only=False):
            if int_only and n_int:
                w = gene_w[int_idx]
                return int(int_idx[np.random.choice(n_int, p=w / w.sum())])
            w = gene_w
            return int(np.random.choice(dim, p=w / w.sum()))

        def move_gene(y, i, sig):
            if is_int[i]:
                if nv[i] <= 1:
                    return
                c_val = int(np.clip(np.round(y[i]), 0, nv[i] - 1))
                if (not is_cat[i]) and np.random.rand() < 0.6:
                    nxt = c_val + (1 if np.random.rand() < 0.5 else -1)
                    if nxt < 0 or nxt >= nv[i]:
                        nxt = c_val - (nxt - c_val)
                else:
                    nxt = np.random.randint(nv[i] - 1)
                    if nxt >= c_val:
                        nxt += 1
                y[i] = nxt
            else:
                y[i] += sig * width[i] * np.random.randn()

        def random_ind():
            x = np.empty(dim)
            if n_cont:
                x[cont_idx] = np.random.uniform(lb[cont_idx], ub[cont_idx])
            if n_int:
                x[int_idx] = np.random.randint(0, nv[int_idx])
            return evaluate(x)

        def tournament(pop):
            i, j = np.random.randint(len(pop), size=2)
            return pop[i] if better(pop[i], pop[j]) else pop[j]

        def stochastic_select(combined, mu, pf=0.45):
            n = len(combined)
            idx = list(range(n))
            for _ in range(n):
                changed = False
                for j in range(n - 1):
                    a = combined[idx[j]]
                    b = combined[idx[j + 1]]
                    if a["feas"] and b["feas"]:
                        swap = a["f"] > b["f"]
                    elif (not a["feas"]) and (not b["feas"]):
                        if np.random.rand() < pf:
                            swap = a["f"] > b["f"]
                        else:
                            swap = a["v"] > b["v"]
                    else:
                        swap = (not a["feas"]) and b["feas"]
                    if swap:
                        idx[j], idx[j + 1] = idx[j + 1], idx[j]
                        changed = True
                if not changed:
                    break
            return [combined[i] for i in idx[:mu]]

        def make_child(p1, p2):
            x1, x2 = p1["x"], p2["x"]
            child = np.empty(dim)
            if n_cont:
                a = np.random.uniform(-0.25, 1.25, n_cont)
                child[cont_idx] = x1[cont_idx] + a * (x2[cont_idx] - x1[cont_idx])
            if n_int:
                m = np.random.rand(n_int) < 0.5
                child[int_idx] = np.where(m, x1[int_idx], x2[int_idx])

            tau = 1.0 / np.sqrt(2.0 * np.sqrt(max(dim, 1)))
            s = np.sqrt(p1["sigma"] * p2["sigma"]) * np.exp(tau * np.random.randn())
            s = float(np.clip(s, 1e-4, 0.5))
            if n_cont:
                child[cont_idx] += s * width[cont_idx] * np.random.randn(n_cont)

            pm = float(np.sqrt(p1["pm"] * p2["pm"]) * np.exp(0.3 * np.random.randn()))
            pm = float(np.clip(pm, min_pm, 0.5))
            if n_int:
                wi = gene_w[int_idx]
                p_gene = np.clip(pm * wi / wi.mean(), 0.0, 0.9)
                for k in np.where(np.random.rand(n_int) < p_gene)[0]:
                    move_gene(child, int_idx[k], 0.0)
            return child, s, pm

        def gene_values(cur_x, i):
            """Candidate replacement values for gene i, nearest integers first."""
            if is_int[i]:
                c_val = int(np.clip(np.round(cur_x[i]), 0, nv[i] - 1))
                vals = [v for v in range(nv[i]) if v != c_val]
                if not is_cat[i]:
                    vals.sort(key=lambda v: abs(v - c_val))
                else:
                    np.random.shuffle(vals)
                return vals
            return [cur_x[i] + sc * width[i] * s for sc in (0.02, 0.2) for s in (-1.0, 1.0)]

        def repair(ind, tries):
            """Violation-directed best-value scan of credit-chosen genes."""
            cur = ind
            for _ in range(tries):
                if cur["feas"] or not can():
                    break
                i = pick_gene(int_only=(np.random.rand() < 0.8))
                vals = gene_values(cur["x"], i)
                if not is_int[i]:
                    vals = vals[:2] if len(vals) > 2 else vals
                elif len(vals) > 8:
                    vals = vals[:8]
                best = None
                for val in vals:
                    if not can():
                        break
                    y = cur["x"].copy()
                    y[i] = val
                    c = evaluate(y)
                    if c is None:
                        break
                    if best is None or better(c, best):
                        best = c
                if best is not None and better(best, cur) and best["v"] <= cur["v"]:
                    cur = best
                    gene_w[i] = min(gene_w[i] * 1.3, 20.0)
                else:
                    gene_w[i] = max(gene_w[i] * 0.98, 0.2)
            return cur

        def sweep(inc, max_evals):
            """Best-improvement coordinate sweep over neighbour values of each gene."""
            cur = inc
            start = st["evals"]
            w = gene_w / gene_w.sum()
            keys_ = np.log(np.random.rand(dim) + 1e-300) / w
            order = np.argsort(-keys_)
            for i in order:
                if not can() or st["evals"] - start >= max_evals:
                    break
                i = int(i)
                if is_int[i] and nv[i] <= 1:
                    continue
                vals = gene_values(cur["x"], i)
                if is_int[i] and len(vals) > 10:
                    vals = vals[:10]
                best = None
                for val in vals:
                    if not can() or st["evals"] - start >= max_evals:
                        break
                    y = cur["x"].copy()
                    if is_int[i]:
                        y[i] = val
                    else:
                        y[i] = np.clip(val, lb[i], ub[i])
                    c = evaluate(y)
                    if c is None:
                        return cur
                    if better(c, cur) and (best is None or better(c, best)):
                        best = c
                if best is not None:
                    cur = best
                    gene_w[i] = min(gene_w[i] * 1.25, 20.0)
                else:
                    gene_w[i] = max(gene_w[i] * 0.97, 0.2)
            return cur

        def relink(cur, tgt, max_evals):
            """Path-relink from cur toward tgt: greedily keep improving single-gene steps."""
            diff = []
            for i in range(dim):
                if is_int[i]:
                    if cur["x"][i] != tgt["x"][i]:
                        diff.append(i)
                elif abs(cur["x"][i] - tgt["x"][i]) > 1e-9:
                    diff.append(i)
            if not diff:
                return cur
            np.random.shuffle(diff)
            start = st["evals"]
            for i in diff:
                if not can() or st["evals"] - start >= max_evals:
                    break
                y = cur["x"].copy()
                if is_int[i]:
                    y[i] = tgt["x"][i]
                else:
                    y[i] = 0.5 * (cur["x"][i] + tgt["x"][i])
                c = evaluate(y)
                if c is None:
                    break
                if better(c, cur):
                    cur = c
            return cur

        def heavy_mutate(elite, strength):
            x = elite["x"].copy()
            if n_cont:
                x[cont_idx] += strength * width[cont_idx] * np.random.randn(n_cont)
            if n_int:
                for i in int_idx:
                    if np.random.rand() < 0.25 and nv[i] > 1:
                        x[i] = np.random.randint(nv[i])
            return x

        def local_search(inc, max_evals):
            """Credit-weighted adaptive 1+1 search; spend-guarded and attempt-capped."""
            cur = inc
            start = st["evals"]
            sig = 0.05
            succ = tries = 0
            max_tries = 6 * max_evals + 10
            total = 0
            while can() and st["evals"] - start < max_evals and total < max_tries:
                total += 1
                y = cur["x"].copy()
                n_moves = 1 + (np.random.rand() < 0.3)
                chosen = []
                for _ in range(n_moves):
                    i = pick_gene()
                    chosen.append(i)
                    move_gene(y, i, sig)
                c = evaluate(y)
                if c is None:
                    break
                tries += 1
                if better(c, cur):
                    cur = c
                    succ += 1
                    for i in chosen:
                        gene_w[i] = min(gene_w[i] * 1.2, 20.0)
                else:
                    for i in chosen:
                        gene_w[i] = max(gene_w[i] * 0.99, 0.2)
                if tries % 10 == 0:
                    rate = succ / 10.0
                    sig = sig * 1.4 if rate > 0.2 else sig * 0.7
                    sig = float(np.clip(sig, 1e-3, 0.3))
                    succ = 0
            return cur

        # ---------------- main loop ----------------
        mu = max(12, min(40, 3 * dim))
        lam = 2 * mu
        patience = 8
        polish_budget = max(2 * dim, int(0.035 * budget))
        ls_budget = max(dim, int(0.01 * budget))
        relink_budget = max(dim, int(0.015 * budget))

        n0 = min(max(2 * mu, 24), budget)
        init = []
        attempts = 0
        while len(init) < n0 and can() and attempts < 10 * n0:
            attempts += 1
            ind = random_ind()
            if ind is not None:
                init.append(ind)
        if not init:
            return st["best_f"], st["best_x"]
        pop = sorted(init, key=key)[:mu]

        best_key_seen = key(pop[0])
        stagn = 0
        gen = 0
        dead_gens = 0
        restarts = 0

        while can():
            gen += 1
            spent0 = st["evals"]
            offspring = []
            attempts = 0
            while len(offspring) < lam and can() and attempts < 4 * lam:
                attempts += 1
                p1 = tournament(pop)
                p2 = tournament(pop)
                x, s, pm = make_child(p1, p2)
                ind = evaluate(x)
                if ind is None:
                    break
                rep_p = 0.5 if ind["v"] < 0.5 else 0.2
                if (not ind["feas"]) and ind["v"] < 1.0 and np.random.rand() < rep_p:
                    rep = repair(ind, 3)
                    if rep is not None:
                        ind = rep
                ind["sigma"] = s
                ind["pm"] = pm
                offspring.append(ind)

            if offspring:
                pop = stochastic_select(pop + offspring, mu)

            # Keep incumbent in population
            if st["best_x"] is not None and not any(
                    p["feas"] and p["f"] == st["best_f"] for p in pop):
                inc = evaluate(st["best_x"])
                if inc is not None:
                    worst = max(range(len(pop)), key=lambda i: key(pop[i]))
                    pop[worst] = inc

            # Spend guard
            if st["evals"] == spent0:
                dead_gens += 1
                if dead_gens >= 2:
                    for _ in range(max(2, mu // 4)):
                        r = random_ind()
                        if r is None:
                            break
                        pop.append(r)
                    pop = stochastic_select(pop, mu)
                    dead_gens = 0
            else:
                dead_gens = 0

            # Incumbent polishing: sweep, then path-relinking toward an archive mate, then 1+1
            ls_period = 2 if st["evals"] < 0.3 * budget else 4
            if gen % ls_period == 0 and st["best_x"] is not None and can():
                inc = evaluate(st["best_x"])
                if inc is not None:
                    improved = sweep(inc, polish_budget)
                    if can() and len(archive) > 1 and np.random.rand() < 0.5:
                        mate = archive[np.random.randint(1, len(archive))]
                        improved = relink(improved, mate, relink_budget)
                    if can():
                        improved = local_search(improved, ls_budget)
                    if better(improved, inc):
                        for i, p in enumerate(pop):
                            if p["feas"] and p["f"] == st["best_f"]:
                                pop[i] = improved
                                break
                        else:
                            pop.append(improved)
                        pop = stochastic_select(pop, mu)

            cur_best = min(pop, key=key)
            cur_key = key(cur_best)
            if cur_key < best_key_seen:
                best_key_seen = cur_key
                stagn = 0
            else:
                stagn += 1

            if stagn >= patience and can():
                restarts += 1
                elite = min(pop, key=key)
                if archive:
                    rank = min(int(np.random.exponential(2.0)), len(archive) - 1)
                    base = dict(archive[rank])
                    base["sigma"], base["pm"] = 0.2, 0.1
                    elite = base if not better(elite, base) else elite
                new_pop = [elite]
                n_mut = mu // 2
                for _ in range(n_mut):
                    if not can():
                        break
                    strength = np.random.uniform(0.03, min(0.3, 0.04 * restarts + 0.08))
                    ind = evaluate(heavy_mutate(elite, strength))
                    if ind is not None:
                        ind["sigma"] = 0.2
                        ind["pm"] = 0.1
                        new_pop.append(ind)
                tries = 0
                while len(new_pop) < mu and can() and tries < 4 * mu:
                    tries += 1
                    r = random_ind()
                    if r is not None:
                        new_pop.append(r)
                if len(new_pop) >= 2:
                    pop = sorted(new_pop, key=key)
                gene_w[:] = np.maximum(gene_w * 0.5 + 0.5, 0.2)
                best_key_seen = key(pop[0])
                stagn = 0

        return st["best_f"], st["best_x"]
